//! Replay of tools/vars_harness/vectors.txt — 117 lines of ground truth
//! generated by compiling the ORIGINAL parser/vars.cc + var_dependency.cc
//! (plus the verbatim parse_conf.cc ParseIpVar body) and driving the exact
//! call sequence below. Neither file has an upstream unit suite, so this
//! replay IS the suite. The driver emits the same byte stream the C probe
//! did (printf labels, hex encodings, inline-PERR/WARN/ABORT lines, VT
//! walks of the path-var table in C's head->next order) and asserts
//! whole-transcript equality: every quirk — define-time ExpandVars,
//! alias id-copies, after-head insertion, cross-table PERR-only logging,
//! ':'-modifier reachability, stuck weak lists after a longjmp, resolve's
//! early-return-still-clears — must land in the same place.

use snort3::parser::messages::ParseMsg;
use snort3::parser::vars::{self as v, VarContext};
use snort3::ports::port_var_table::PortVarTable;
use snort3::sfip::sf_vartable::Vartable;

fn hx(b: &[u8]) -> String {
    b.iter().map(|c| format!("{c:02x}")).collect()
}
fn unhex(s: &str) -> String {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap() as char)
        .collect()
}

/// Drain ctx.diag into harness-prefix form. C printf'd these inline:
/// "PERR "/"WARN(3) "/"ABORT " + format + '\n' (a format string's own
/// trailing '\n' — the redefined-var warning — yields a blank line).
fn drain(ctx: &mut VarContext, out: &mut String) {
    for m in ctx.diag.drain(..) {
        match m {
            ParseMsg::Error(s) => out.push_str(&format!("PERR {s}\n")),
            ParseMsg::Warning(g, s) => out.push_str(&format!("WARN({g}) {s}\n")),
            ParseMsg::Abort(s) => out.push_str(&format!("ABORT {s}\n")),
        }
    }
}

/// walk_vars(): the C probe's do/while over the circular list (head first,
/// then head->next chain) + VTNEXT id line. C's head is never non-null-but-
/// empty (DeleteVars nulls it), so Some(t) always has >= 1 entry.
fn walk(ctx: &VarContext, out: &mut String) {
    if ctx.var_table.is_none() {
        out.push_str(&format!("VT (empty) id_next={}\n", ctx.var_id));
        return;
    }
    let t = ctx.var_table.as_ref().unwrap();
    for e in t {
        out.push_str(&format!(
            "VT {} {} id={}\n",
            hx(e.name.as_bytes()),
            hx(e.value.as_bytes()),
            e.id
        ));
    }
    out.push_str(&format!("VTNEXT id={}\n", ctx.var_id));
}

fn cases<const N: usize>(hexes: [&str; N]) -> Vec<String> {
    hexes.iter().map(|h| unhex(h)).collect()
}

#[test]
fn vars_harness_full_transcript_replay() {
    let vectors = include_str!("../tools/vars_harness/vectors.txt");

    let mut ip = Vartable::new();
    let mut pvt = PortVarTable::create();
    // probe main(): sfvt_define seeds (names verbatim, '$' included)
    ip.define("$FOO", "[1.2.3.4,5.6.7.8]");
    ip.define("BAR", "9.9.9.9");
    let mut o = String::new();

    // ===== VarIsIpAddr table (C probe runs these before any defines) =====
    for s in cases([
        "5b5d", "21205b205d", "312e322e332e34", "312e322e33", "312f38", "3a3a31", "3a303a78",
        "3a78313a", "616e79", "616e797468696e67", "24464f4f", "464f4f", "244d495353494e47",
        "21312e322e332e34", "5b312e322e332e345d", "203a3a31", "2d312e322e332e34",
        "31302e302e302e302f38", "313a322f33", "24", "2446", "424152", "612e622e63",
    ]) {
        o.push_str(&format!("VIA {} {}\n", hx(s.as_bytes()), v::var_is_ip_addr(&ip, &s) as u8));
    }

    // ===== VarIsIpList table =====
    for s in cases([
        "5b312e322e332e342c352e362e372e385d", "5b312e322e332e342c785d", "312e322e332e34",
        "5b615d5b625d", "5b312e322e332e34", "215b312e322e332e342c616e795d", "5b5b5d5d", "5b205d",
        "5b24464f4f2c616e795d", "21616e79", "5b244d495353494e472c312e322e332e345d",
        "5b312e322e332e342c",
    ]) {
        o.push_str(&format!("VIL {} {}\n", hx(s.as_bytes()), v::var_is_ip_list(&ip, &s) as u8));
    }

    // context takes over the tables from here (C: same globals throughout)
    let mut c = VarContext::new(&mut ip, &mut pvt);

    // ===== ParsePathVar: C prints fn diagnostics (inline), then walk_vars =====
    macro_rules! pp {
        ($name:expr, $val:expr) => {{
            let res = v::parse_path_var(&mut c, $name, $val);
            drain(&mut c, &mut o);
            walk(&c, &mut o);
            res.is_err()
        }};
    }

    pp!("$HOME_NET", Some("[192.168.0.0/16]"));
    pp!("$WEB_SERVERS", Some("$HOME_NET")); // ExpandVars of value aborts: name+1 "HOME_NET" not in table
    pp!("$home_net", Some("10.0.0.0/8"));
    pp!("$P", Some("a$HOME_NET b"));
    // PQ/PR: the C probe prints its abort flag BETWEEN the abort printf
    // and walk_vars ($Q has a walk after; $R does NOT — the walk comes
    // after $S), so these stay split:
    {
        let res = v::parse_path_var(&mut c, "$Q", Some("$MISSING_VAR"));
        drain(&mut c, &mut o);
        o.push_str(&format!("PQ abort={}\n", res.is_err() as u8));
        walk(&c, &mut o);
    }
    {
        let res = v::parse_path_var(&mut c, "$R", None);
        drain(&mut c, &mut o);
        o.push_str(&format!("PR abort={}\n", res.is_err() as u8));
    }
    pp!("$S", Some("$FOO"));
    pp!("$T", Some("pre$(WEB_SERVERS)post"));
    pp!("$HTTP_PORTS", Some("x"));
    // probe: two g_parsepath calls, ONE walk after the pair
    v::parse_path_var(&mut c, "$X", Some("5")).ok();
    drain(&mut c, &mut o);
    v::parse_path_var(&mut c, "$X", Some("$X")).ok();
    drain(&mut c, &mut o);
    walk(&c, &mut o);
    pp!("HOME_NET", Some("11.0.0.0/8"));
    // VarSearch("HOME_NET")
    {
        let s = v::var_search(&mut c, "HOME_NET").unwrap();
        o.push_str(&format!("VSRHOME2 {}\n", hx(s.as_bytes())));
    }

    // ===== ParsePortVar =====
    o.push_str("PPT start\n");
    v::parse_port_var(&mut c, "$HOME_NET", "[80]").ok();
    v::parse_port_var(&mut c, "$HTTP_PORTS", "[80,443]").ok();
    v::parse_port_var(&mut c, "$ALL_PORTS", "[any]").ok();
    v::parse_port_var(&mut c, "$NEG_ANY", "[!any]").ok();
    v::parse_port_var(&mut c, "$BADPORT", "[80:x]").ok();
    v::parse_port_var(&mut c, "$HTTP_PORTS", "[8080]").ok();
    drain(&mut c, &mut o);
    o.push_str("PPT end\n");

    // ===== VarSearch probes =====
    for (label, name) in
        [("VSRHTTP", "HTTP_PORTS"), ("VSRHOME", "HOME_NET"), ("VSRFOO", "FOO"), ("VSRNOPE", "NOPE")]
    {
        let r = v::var_search(&mut c, name);
        // a search that aborts prints only the ABORT line (g_expand-style);
        // the empty EXP/VSR line still prints the result when it returns.
        match r {
            Ok(s) => o.push_str(&format!("{label} {}\n", hx(s.as_bytes()))),
            Err(_) => drain(&mut c, &mut o),
        }
    }

    // ===== ExpandVars (g_expand: on abort only the ABORT line prints) =====
    macro_rules! ex {
        ($inp:expr) => {{
            let res = v::expand_vars(&mut c, $inp);
            drain(&mut c, &mut o);
            if let Ok(out) = res {
                o.push_str(&format!(
                    "EXP {} -> {}\n",
                    hx($inp.as_bytes()),
                    hx(out.as_bytes())
                ));
            }
        }};
    }
    ex!("$HOME_NET");
    ex!("plain");
    ex!("has \"quoted $NOT_EXPANDED\" text");
    ex!("$(WEB_SERVERS)");
    ex!("$MISSING-");
    ex!("$MISSING-abc");
    ex!("$HOME_NET-5");
    ex!("$MISSINGQ?boom");
    ex!("$MISSINGQ?");
    ex!("$T");
    ex!("a$FOOb");
    ex!("$");
    ex!("$$HOME_NET");
    ex!("$(NOPE:-abc)");
    ex!("$(HOME_NET:-x)");
    ex!("$(NOPE:?boom)");
    ex!("$(NOPE:?)");
    ex!("$(NOPE:)");
    ex!("$(NOPE:ax)");
    ex!("$(NOPE:-a:b)");
    ex!("$(");

    // ===== resolve_ports stuck-state trilogy =====
    o.push_str("RESOLVE start\n");
    let abort = v::resolve_ports(&mut c).is_err();
    drain(&mut c, &mut o);
    o.push_str(&format!(
        "RESOLVE abort={} resolving={}\n",
        abort as u8, c.is_resolving_ports() as u8
    ));
    let abort = v::resolve_ports(&mut c).is_err();
    drain(&mut c, &mut o);
    o.push_str(&format!(
        "RESOLVE2 abort={} resolving={}\n",
        abort as u8, c.is_resolving_ports() as u8
    ));
    c.push_to_weak_ports("$BAD2", "[1:x]");
    let abort = v::resolve_ports(&mut c).is_err();
    drain(&mut c, &mut o);
    o.push_str(&format!(
        "RESOLVE3 abort={} resolving={}\n",
        abort as u8, c.is_resolving_ports() as u8
    ));
    {
        let s = v::var_search(&mut c, "BADPORT").unwrap();
        o.push_str(&format!("VSRBAD {}\n", hx(s.as_bytes())));
    }
    walk(&c, &mut o);

    // ===== weak nets (real ParseIpVar callback) =====
    v::parse_ip_var(&mut c, "NET1", "$NET0").ok();
    v::parse_ip_var(&mut c, "NETBAD", "$NOPE").ok();
    drain(&mut c, &mut o);
    o.push_str("RESOLVENETS start\n");
    v::resolve_nets(&mut c).ok();
    drain(&mut c, &mut o);
    o.push_str(&format!("RESOLVENETS end resolving={}\n", c.is_resolving_nets() as u8));
    let ret = v::parse_ip_var(&mut c, "NET0", "[3.3.3.3]").unwrap();
    drain(&mut c, &mut o);
    o.push_str(&format!("IPVARNET0 ret={}\n", ret as u8));
    o.push_str("RESOLVENETS2 start\n");
    v::resolve_nets(&mut c).ok();
    drain(&mut c, &mut o);
    o.push_str("RESOLVENETS2 end\n");
    {
        let s = v::var_search(&mut c, "NET1").unwrap();
        o.push_str(&format!("VSRNET1 {}\n", hx(s.as_bytes())));
    }
    {
        let s = v::var_search(&mut c, "NET0").unwrap();
        o.push_str(&format!("VSRNET0 {}\n", hx(s.as_bytes())));
    }

    // ===== alias id-copy on a NON-empty table =====
    pp!("AL0", Some("[9.9.9.9]"));
    // g_parsepath("$AL1", "$AL0"): alias key scan matches stored "AL0"
    pp!("$AL1", Some("$AL0"));

    // ===== DeleteVars =====
    v::delete_vars(&mut c);
    walk(&c, &mut o);

    // ===== whole-transcript equality =====
    let expected: Vec<&str> = vectors.trim_end_matches('\n').split('\n').collect();
    let got: Vec<&str> = o.trim_end_matches('\n').split('\n').collect();

    // line-by-line diff for a readable failure
    let n = expected.len().max(got.len());
    let aligned: Vec<String> = (0..n)
        .filter_map(|i| {
            let e = expected.get(i).copied().unwrap_or("<none>");
            let g = got.get(i).copied().unwrap_or("<none>");
            if e != g {
                Some(format!("line {}:\n  C : {e:?}\n  RS: {g:?}", i + 1))
            } else {
                None
            }
        })
        .collect();
    assert!(
        aligned.is_empty(),
        "transcript mismatch (C={} Rust={}, {} lines differ; first six):\n{}",
        expected.len(),
        got.len(),
        aligned.len(),
        aligned[..aligned.len().min(6)].join("\n")
    );
}
